; inrom.asm -- chapter 52: self-modifying code left in the ROM
; generated by gen52.py
        INCLUDE "msx.inc"
        OUTPUT "inrom.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
ticks   EQU VARS                ; the player's ticks, two bytes (chapter 37)
owed    EQU VARS + 2            ; lines owed to the player, two bytes
lines   EQU VARS + 4            ; the machine's lines a frame: 313 or 262
tick    EQU VARS + 6            ; ticks still to the next row
step    EQU VARS + 7            ; the song's step, two bytes
barno   EQU VARS + 9            ; the step's number
rowno   EQU VARS + 10           ; the row in the bar
frames  EQU VARS + 11           ; frames counted by isr
shadow  EQU VARS + $20          ; R0 to R10, as the next tick sends them
chan_a  EQU shadow + 11         ; the channels, CHAN bytes each
chan_b  EQU chan_a + CHAN
chan_c  EQU chan_b + CHAN
chan_x  EQU chan_c + CHAN       ; the effect: a fourth channel, on C's registers
score   EQU $C400               ; three BCD bytes (chapter 40)
hi      EQU score + 3           ; the best, three more
shown   EQU score + $100        ; the six bytes last sent, a page on
at      EQU $C410               ; pixels the scroll has gone, 0 to 511, two bytes
col     EQU at + 2              ; the column shown, 0 to 63: at / 8
table   EQU at + 3              ; the name table not shown: $18 or $1C, its high byte
need    EQU at + 4              ; rows of the next window still to write
wsrc    EQU at + 5              ; where they come from in pmap, two bytes
wdst    EQU at + 7              ; and where they go in the VRAM, two bytes
last    EQU at + 9              ; frames, the last time the logic counted them
counted EQU at + 10             ; the frames it counted
seed    EQU at + 11             ; random's state, two bytes (chapter 41)
copy    EQU $C480               ; the sprites' attributes, and $D0
MOVES   EQU $C800               ; move's code, copied into the RAM at INIT
ROWS    EQU 21
PW      EQU 95                ; a row of pmap
NB      EQU 184                ; the pairs' shapes at a shift, in bytes
NBALLS  EQU 9                   ; the balls
SAT     EQU $1B00               ; the sprites' attributes
SPAT    EQU $3800               ; and patterns
DIGIT0  EQU $F0                 ; the status line's digits: patterns $F0 to $F9
SCORE_AT EQU $1AC8             ; the score's first digit, in the table at $1800
HI_AT   EQU $1AD8               ; and the best's
XMAX    EQU 240                 ; a ball's X: 0 to XMAX
YMIN    EQU 8                   ; and its Y: YMIN to YMAX
YMAX    EQU 104
WAITS   EQU 0                   ; rows to wait; an effect: ticks to sound
NOTE    EQU 1                   ; the note, 0 for a rest
INSTR   EQU 2                   ; the instrument
PATTERN EQU 3                   ; the next event
VOLUME  EQU 5                   ; this tick's level in the volume table
PITCHES EQU 7                   ; this tick's semitones
FIRST   EQU 9                   ; the pitch table's first byte
MIXER   EQU 11                  ; the instrument's TONE and NOISE
NOISEP  EQU 12                  ; its noise's period
SHPER   EQU 13                  ; where in shadow its period goes
SHLEV   EQU 15                  ; and its level
TMASK   EQU 17                  ; R7 with its tone bit at 0
NMASK   EQU 18                  ; R7 with its noise bit at 0
PRIO    EQU 19                  ; an effect's priority
CHAN    EQU 20                  ; bytes a channel
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; WHERE IT BREAKS. patch.asm with move left in the cartridge.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800, and $1C00 with R#2 = 7
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the pairs at shift 0
        ld hl, shifts
        ld bc, NB << 8 | VDP_DATA
        otir
        VRAM_WRITE $2000        ; their colours, which no shift changes
        ld hl, pcols
        ld b, NB
        otir
        VRAM_WRITE $0700        ; the status line's letters
        ld hl, letters
        ld b, 64
        otir
        VRAM_WRITE $0780        ; and digits
        ld hl, digits
        ld b, 80
        otir
        VRAM_WRITE $2700        ; white on black
        ld b, 64
.lc:    ld a, $F1
        out (VDP_DATA), a
        djnz .lc
        VRAM_WRITE $2780
        ld b, 80
.dc:    ld a, $F1
        out (VDP_DATA), a
        djnz .dc
        VRAM_WRITE $1AA0        ; the status line, in both tables
        ld hl, statusn
        ld b, 96
        otir
        VRAM_WRITE $1EA0
        ld hl, statusn
        ld b, 96
        otir
        VRAM_WRITE SPAT         ; the ball, sprite patterns 0 to 3
        ld hl, ball
        ld b, 32
        otir
        ld hl, atts             ; their attributes
        ld de, copy
        ld bc, 4 * NBALLS + 1
        ldir
        ld hl, nums             ; score and hi
        ld de, score
        ld bc, 6
        ldir
        ld hl, nums             ; as the status line has them
        ld de, shown
        ld bc, 6
        ldir
        ld hl, 0
        ld (at), hl
        xor a
        ld (col), a
        ld (need), a
        ld hl, 1
        ld (seed), hl
        ld hl, pmap             ; window 0 into the table at $1800, shown
        ld (wsrc), hl
        ld hl, $1800
        ld (wdst), hl
        ld b, ROWS
        di
        call rows
        ld hl, pmap + 1         ; window 1 into the one at $1C00
        ld (wsrc), hl
        ld hl, $1C00
        ld (wdst), hl
        ld b, ROWS
        di
        call rows
        di
        ld a, $1C
        ld (table), a           ; not shown
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld hl, 262              ; 60 Hz ...
        jr nc, .rlines
        ld hl, 313              ; ... and 50 Hz
.rlines:ld (lines), hl
        ld hl, 0
        ld (owed), hl
        ld (ticks), hl
        ld a, 1                 ; the first tick reads a row
        ld (tick), a
        xor a
        ld (barno), a
        ld (rowno), a
        ld (frames), a
        ld hl, song - 6         ; the step before the first
        ld (step), hl
        ld hl, start            ; shadow and the four channels
        ld de, shadow
        ld bc, 91
        ldir
        ld a, (frames)
        ld (last), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over (chapter 39)
        VDP_REG 1, $E2          ; display on, the frame's signal, sprites 16 x 16
main:   ei
frame:  halt                    ; the interrupt: the frame counted, the tune
        di
        ld a, DARK_BLUE
        out (VDP_CTRL), a
        ld a, $87
m0:     out (VDP_CTRL), a       ; R#7: the sends
        ei
        call show               ; the scroll: patterns, and R#2 at a new column
        call sprites            ; the balls' attributes
        call status             ; the score and the best
        di
        ld a, LIGHT_GREEN
        out (VDP_CTRL), a
        ld a, $87
m1:     out (VDP_CTRL), a       ; R#7: the logic
        ei
        call input              ; the keys and the joystick
        ld a, (frames)          ; the frames counted by isr ...
        ld hl, last
        ld b, a
        sub (hl)                ; ... since the logic last counted them
        ld (hl), b
        ld (counted), a
        ld b, a
.steps: push bc
        call move               ; a frame of the game for each
        pop bc
        djnz .steps
        call tests              ; every two balls
        di
        ld a, BLACK
        out (VDP_CTRL), a
        ld a, $87
m2:     out (VDP_CTRL), a       ; R#7: the window
        ei
        call nextwin            ; the next window, into the table not shown
        di
        ld a, WHITE
        out (VDP_CTRL), a
        ld a, $87
m3:     out (VDP_CTRL), a       ; R#7: waiting
        ei
        jp frame

; show: the pairs' patterns at the scroll's shift, NB bytes after the paper
; (chapter 29), each shift in a page of its own: the page is high shifts plus
; the shift, and no multiplication. The NB bytes go by NB OUTIs one after
; another, 18 T-states a byte: the border takes them as fast as that (chapter
; 20). And when the scroll has reached a new column, the table that holds it
; shown with R#2, and the next window to be written
show:   VRAM_WRITE $0000        ; 40
        ld a, (at)              ; 14
        and 7                   ;  8  the shift
        add a, high shifts      ;  8
        ld h, a                 ;  5
        ld l, 0                 ;  8  HL: its page
        ld c, VDP_DATA          ;  8
        DUP NB
        outi                    ; 18
        EDUP
        ld hl, (at)             ; 17
        ld a, l                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8  at / 8 ...
        bit 0, h                ; 10
        jr z, .col              ; 13, or 8
        or $20                  ;  8  ... with at's ninth bit
.col:   ld hl, col              ; 11
        cp (hl)                 ;  8
        ret z                   ; 12, or 6  the same column
        ld (hl), a              ;  8  a new one
        inc a                   ;  5
        and 63                  ;  8  the next window's column
        ld e, a                 ;  5
        ld d, 0                 ;  8
        ld hl, pmap             ; 11
        add hl, de              ; 12
        ld (wsrc), hl           ; 17  its first pair
        ld a, (table)           ; 14  the table not shown, which has the new one
        ld h, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5  $18 or $1C: 6 or 7
        out (VDP_CTRL), a       ; 12
        ld a, $82               ;  8
        out (VDP_CTRL), a       ; 12  R#2: shown
        ld a, h                 ;  5
        xor $18 ^ $1C           ;  8
        ld (table), a           ; 14  the other table is not shown now
        ld h, a                 ;  5
        ld l, 0                 ;  8
        ld (wdst), hl           ; 17  where the next window goes
        ld a, ROWS              ;  8
        ld (need), a            ; 14  all its rows to write
        ret                     ; 11


; sprites: the balls' attributes from the copy, after the paper, by OUTIs one
; after another. Uses BC, HL
sprites: VRAM_WRITE SAT         ; 40
        ld hl, copy             ; 11
        ld c, VDP_DATA          ;  8
        DUP 4 * NBALLS + 1
        outi                    ; 18
        EDUP
        ret                     ; 11

; putbcd: A = a BCD byte, the VRAM address set -> its two digits sent, as
; the patterns from DIGIT0 (chapter 40's, with an OR). Uses A, C
putbcd: ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5  the first digit to bits 3 to 0
        and $0F                 ;  8
        or DIGIT0               ;  8  its pattern
        out (VDP_DATA), a       ; 12
        ld a, c                 ;  5
        and $0F                 ;  8  the second digit
        or DIGIT0               ;  8
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; update: HL = a number, three BCD bytes, with a copy of the three last sent
; 256 bytes on; DE = the VRAM address of its first digit in the table at
; $1800, bit 6 set -> each byte that differs from its copy sent to both
; tables, and copied (chapter 40). Uses A, BC, DE, HL
update: ld b, 3                 ;  8  three bytes
.byte:  ld a, (hl)              ;  8  a byte of the number
        inc h                   ;  5  the page of the bytes sent
        cp (hl)                 ;  8
        jr z, .same             ; 13, or 8  on the screen already
        ld (hl), a              ;  8  it will be
        call putpair            ; 18  in the table at $1800
        ld a, d                 ;  5
        xor $04                 ;  8
        ld d, a                 ;  5  and in the one at $1C00
        ld a, (hl)              ;  8
        call putpair            ; 18
        ld a, d                 ;  5
        xor $04                 ;  8
        ld d, a                 ;  5
.same:  inc e                   ;  5
        inc e                   ;  5  past its two names
        dec h                   ;  5  back to the number
        inc l                   ;  5  and its next byte
        djnz .byte              ; 14, or 9
        ret                     ; 11

; putpair: A = a BCD byte, DE = the address of its first digit -> sent.
; Uses A, C
putpair: ld c, a                ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, c                 ;  5
        jp putbcd               ; 11

; status: the score and the best on the status line, the pairs that changed
status: ld hl, score            ; 11
        ld de, SCORE_AT | $4000 ; 11
        call update             ; 18
        ld hl, hi               ; 11
        ld de, HI_AT | $4000    ; 11
        jp update               ; 11

; input: row 8 of the keyboard and joystick 1, with the interrupts off
; (chapters 34, 35 and 37): LEFT or the stick to the left sends the first
; ball left, RIGHT or the stick to the right sends it right. Uses A, B, C, HL
input:  di                      ;  5
        in a, (PPI_C)           ; 12
        and $F0                 ;  8  the top four bits kept
        or 8                    ;  8
        out (PPI_C), a          ; 12  row 8
        in a, (PPI_B)           ; 12  LEFT is bit 4, RIGHT bit 7
        ld c, a                 ;  5
        xor a                   ;  5  port 1
        call joy                ; 18  left is bit 2, right bit 3
        ei                      ;  5
        ld hl, move.dx0         ; 11  the first ball's X direction
        bit 4, c                ; 10
        jr z, .left             ; 13, or 8  LEFT
        bit 2, a                ; 10
        jr nz, .right           ; 13, or 8  nor the stick to the left
.left:  ld (hl), $3D            ; 11  DEC A
        ret                     ; 11
.right: bit 7, c                ; 10
        jr z, .go               ; 13, or 8  RIGHT
        bit 3, a                ; 10
        ret nz                  ; 12, or 6  nor the stick to the right
.go:    ld (hl), $3C            ; 11  INC A
        ret                     ; 11

; move: patch.asm's, left in the cartridge
move:   ld hl, (at)             ; 17
        inc hl                  ;  7
        ld a, h                 ;  5
        and 1                   ;  8  512 pixels, then 0 again
        ld h, a                 ;  5
        ld (at), hl             ; 17
        ld a, (copy + 1)        ; 14  ball 0: its X
.dx0:   inc a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx0            ; 11, or 18  past the left or the right edge
        ld (copy + 1), a        ; 14
        ld a, (copy + 0)        ; 14  its Y
.dy0:   inc a                   ;  5
        cp YMIN                 ;  8
        call c, ty0             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty0            ; 11, or 18  below its bottom
        ld (copy + 0), a        ; 14
        ld a, (copy + 5)        ; 14  ball 1: its X
.dx1:   dec a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx1            ; 11, or 18  past the left or the right edge
        ld (copy + 5), a        ; 14
        ld a, (copy + 4)        ; 14  its Y
.dy1:   inc a                   ;  5
        cp YMIN                 ;  8
        call c, ty1             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty1            ; 11, or 18  below its bottom
        ld (copy + 4), a        ; 14
        ld a, (copy + 9)        ; 14  ball 2: its X
.dx2:   inc a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx2            ; 11, or 18  past the left or the right edge
        ld (copy + 9), a        ; 14
        ld a, (copy + 8)        ; 14  its Y
.dy2:   dec a                   ;  5
        cp YMIN                 ;  8
        call c, ty2             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty2            ; 11, or 18  below its bottom
        ld (copy + 8), a        ; 14
        ld a, (copy + 13)       ; 14  ball 3: its X
.dx3:   dec a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx3            ; 11, or 18  past the left or the right edge
        ld (copy + 13), a       ; 14
        ld a, (copy + 12)       ; 14  its Y
.dy3:   dec a                   ;  5
        cp YMIN                 ;  8
        call c, ty3             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty3            ; 11, or 18  below its bottom
        ld (copy + 12), a       ; 14
        ld a, (copy + 17)       ; 14  ball 4: its X
.dx4:   dec a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx4            ; 11, or 18  past the left or the right edge
        ld (copy + 17), a       ; 14
        ld a, (copy + 16)       ; 14  its Y
.dy4:   inc a                   ;  5
        cp YMIN                 ;  8
        call c, ty4             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty4            ; 11, or 18  below its bottom
        ld (copy + 16), a       ; 14
        ld a, (copy + 21)       ; 14  ball 5: its X
.dx5:   inc a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx5            ; 11, or 18  past the left or the right edge
        ld (copy + 21), a       ; 14
        ld a, (copy + 20)       ; 14  its Y
.dy5:   dec a                   ;  5
        cp YMIN                 ;  8
        call c, ty5             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty5            ; 11, or 18  below its bottom
        ld (copy + 20), a       ; 14
        ld a, (copy + 25)       ; 14  ball 6: its X
.dx6:   dec a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx6            ; 11, or 18  past the left or the right edge
        ld (copy + 25), a       ; 14
        ld a, (copy + 24)       ; 14  its Y
.dy6:   inc a                   ;  5
        cp YMIN                 ;  8
        call c, ty6             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty6            ; 11, or 18  below its bottom
        ld (copy + 24), a       ; 14
        ld a, (copy + 29)       ; 14  ball 7: its X
.dx7:   inc a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx7            ; 11, or 18  past the left or the right edge
        ld (copy + 29), a       ; 14
        ld a, (copy + 28)       ; 14  its Y
.dy7:   inc a                   ;  5
        cp YMIN                 ;  8
        call c, ty7             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty7            ; 11, or 18  below its bottom
        ld (copy + 28), a       ; 14
        ld a, (copy + 33)       ; 14  ball 8: its X
.dx8:   inc a                   ;  5  its direction, INC A or DEC A
        cp XMAX + 1             ;  8
        call nc, tx8            ; 11, or 18  past the left or the right edge
        ld (copy + 33), a       ; 14
        ld a, (copy + 32)       ; 14  its Y
.dy8:   dec a                   ;  5
        cp YMIN                 ;  8
        call c, ty8             ; 11, or 18  above the sky's top
        cp YMAX + 1             ;  8
        call nc, ty8            ; 11, or 18  below its bottom
        ld (copy + 32), a       ; 14
        ret                     ; 11

; tx0, ty0 and the others: a ball past an edge -> its direction turned, and A
; its place after a step the new way
tx0:    ld hl, move.dx0         ; 11
        ld a, (copy + 1)        ; 14  the X before the step
        jp turn                 ; 11
ty0:    ld hl, move.dy0         ; 11
        ld a, (copy + 0)        ; 14
        jp turn                 ; 11
tx1:    ld hl, move.dx1         ; 11
        ld a, (copy + 5)        ; 14  the X before the step
        jp turn                 ; 11
ty1:    ld hl, move.dy1         ; 11
        ld a, (copy + 4)        ; 14
        jp turn                 ; 11
tx2:    ld hl, move.dx2         ; 11
        ld a, (copy + 9)        ; 14  the X before the step
        jp turn                 ; 11
ty2:    ld hl, move.dy2         ; 11
        ld a, (copy + 8)        ; 14
        jp turn                 ; 11
tx3:    ld hl, move.dx3         ; 11
        ld a, (copy + 13)       ; 14  the X before the step
        jp turn                 ; 11
ty3:    ld hl, move.dy3         ; 11
        ld a, (copy + 12)       ; 14
        jp turn                 ; 11
tx4:    ld hl, move.dx4         ; 11
        ld a, (copy + 17)       ; 14  the X before the step
        jp turn                 ; 11
ty4:    ld hl, move.dy4         ; 11
        ld a, (copy + 16)       ; 14
        jp turn                 ; 11
tx5:    ld hl, move.dx5         ; 11
        ld a, (copy + 21)       ; 14  the X before the step
        jp turn                 ; 11
ty5:    ld hl, move.dy5         ; 11
        ld a, (copy + 20)       ; 14
        jp turn                 ; 11
tx6:    ld hl, move.dx6         ; 11
        ld a, (copy + 25)       ; 14  the X before the step
        jp turn                 ; 11
ty6:    ld hl, move.dy6         ; 11
        ld a, (copy + 24)       ; 14
        jp turn                 ; 11
tx7:    ld hl, move.dx7         ; 11
        ld a, (copy + 29)       ; 14  the X before the step
        jp turn                 ; 11
ty7:    ld hl, move.dy7         ; 11
        ld a, (copy + 28)       ; 14
        jp turn                 ; 11
tx8:    ld hl, move.dx8         ; 11
        ld a, (copy + 33)       ; 14  the X before the step
        jp turn                 ; 11
ty8:    ld hl, move.dy8         ; 11
        ld a, (copy + 32)       ; 14
        jp turn                 ; 11

; turn: HL = where a direction is, INC A or DEC A, A = a place -> the
; direction the other way from now on, and A the place after a step that way.
; INC A is $3C and DEC A $3D: bit 0 is the way. Uses B
turn:   ld b, a                 ;  5  the place
        ld a, (hl)              ;  8
        xor 1                   ;  8  INC A becomes DEC A, DEC A INC A
        ld (hl), a              ;  8  written into move's code
        rrca                    ;  5  carry: DEC A, to the left or up
        ld a, b                 ;  5
        jr c, .back             ; 13, or 8
        inc a                   ;  5
        ret                     ; 11
.back:  dec a                   ;  5
        ret                     ; 11

; tests: every two balls, the first with each after it, unrolled: for each
; first ball its X and Y less 15 in B and C and its number in D, then for
; each ball after it its X at a fixed address, less B: the two are less than
; 16 apart in X when that is below 31, and only then the CALL is taken. Uses
; A, BC, D, and near and bump the others
tests:  ld a, (copy + 1)        ; 14  ball 0
        sub 15                  ;  8
        ld b, a                 ;  5  B: its X less 15
        ld a, (copy + 0)        ; 14
        sub 15                  ;  8
        ld c, a                 ;  5  C: its Y less 15
        ld d, 0                 ;  8  D: its number
        ld a, (copy + 5)        ; 14  ball 1
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n1             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 9)        ; 14  ball 2
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n2             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 13)       ; 14  ball 3
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n3             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 17)       ; 14  ball 4
