        cp 31                   ;  8
        call c, .n6             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 29)       ; 14  ball 7
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n7             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 33)       ; 14  ball 8
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n8             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 13)       ; 14  ball 3
        sub 15                  ;  8
        ld b, a                 ;  5  B: its X less 15
        ld a, (copy + 12)       ; 14
        sub 15                  ;  8
        ld c, a                 ;  5  C: its Y less 15
        ld d, 3                 ;  8  D: its number
        ld a, (copy + 17)       ; 14  ball 4
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n4             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 21)       ; 14  ball 5
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n5             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 25)       ; 14  ball 6
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n6             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 29)       ; 14  ball 7
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n7             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 33)       ; 14  ball 8
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n8             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 17)       ; 14  ball 4
        sub 15                  ;  8
        ld b, a                 ;  5  B: its X less 15
        ld a, (copy + 16)       ; 14
        sub 15                  ;  8
        ld c, a                 ;  5  C: its Y less 15
        ld d, 4                 ;  8  D: its number
        ld a, (copy + 21)       ; 14  ball 5
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n5             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 25)       ; 14  ball 6
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n6             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 29)       ; 14  ball 7
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n7             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 33)       ; 14  ball 8
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n8             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 21)       ; 14  ball 5
        sub 15                  ;  8
        ld b, a                 ;  5  B: its X less 15
        ld a, (copy + 20)       ; 14
        sub 15                  ;  8
        ld c, a                 ;  5  C: its Y less 15
        ld d, 5                 ;  8  D: its number
        ld a, (copy + 25)       ; 14  ball 6
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n6             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 29)       ; 14  ball 7
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n7             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 33)       ; 14  ball 8
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n8             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 25)       ; 14  ball 6
        sub 15                  ;  8
        ld b, a                 ;  5  B: its X less 15
        ld a, (copy + 24)       ; 14
        sub 15                  ;  8
        ld c, a                 ;  5  C: its Y less 15
        ld d, 6                 ;  8  D: its number
        ld a, (copy + 29)       ; 14  ball 7
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n7             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 33)       ; 14  ball 8
        sub b                   ;  5  its X less ours, plus 15
        cp 31                   ;  8
        call c, .n8             ; 11, or 18  less than 16 apart in X
        ld a, (copy + 29)       ; 14  ball 7
        sub 15                  ;  8
        ld b, a                 ;  5  B: its X less 15
        ld a, (copy + 28)       ; 14
        sub 15                  ;  8
        ld c, a                 ;  5  C: its Y less 15
        ld d, 7                 ;  8  D: its number
        ld a, (copy + 33)       ; 14  ball 8
