; .n1 to .n8: ball j near the first in X -> its Y tested, and if it
; is near in Y too, near with E = j
.n1:    ld a, (copy + 4)        ; 14  ball 1
        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 1                 ;  8
        jp near                 ; 11
.n2:    ld a, (copy + 8)        ; 14  ball 2
        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 2                 ;  8
        jp near                 ; 11
.n3:    ld a, (copy + 12)       ; 14  ball 3
        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 3                 ;  8
        jp near                 ; 11
.n4:    ld a, (copy + 16)       ; 14  ball 4
        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 4                 ;  8
        jp near                 ; 11
.n5:    ld a, (copy + 20)       ; 14  ball 5
        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 5                 ;  8
        jp near                 ; 11
.n6:    ld a, (copy + 24)       ; 14  ball 6
        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 6                 ;  8
