        sub c                   ;  5
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart in Y
        ld e, 8                 ;  8
        jp near                 ; 11

; near: D, E = the numbers of two balls whose boxes meet, B and C the first's
; X and Y less 15 -> touched, and if a pixel of one is a pixel of the other,
; bump. Keeps BC and DE
near:   push bc                 ; 12
        push de                 ; 12
        ld a, b                 ;  5
        add a, 15               ;  8
        ld b, a                 ;  5  B: the first's X
        ld a, c                 ;  5
        add a, 15               ;  8
        ld c, a                 ;  5  C: its Y
        ld a, e                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, low copy         ;  8
        ld l, a                 ;  5
        ld h, high copy         ;  8  HL: the second's Y and X, in the copy
        ld e, (hl)              ;  8
        inc l                   ;  5
        ld d, (hl)              ;  8  D, E: its X and Y
        call touched            ; 18
        jr z, .apart            ; 13, or 8  the boxes meet, the pixels do not
        pop de                  ; 11
        push de                 ; 12
        call bump               ; 18  D and E: the two
.apart: pop de                  ; 11
        pop bc                  ; 11
        ret                     ; 11

; bump: D, E = the numbers of two balls that touch -> if they come together,
; both go back the way they came, ten points are scored, and an effect chosen
; by random starts. The directions are move's INC A and DEC A: xops says where
; each ball's X direction is, and its Y direction is 12 bytes on. INC A, $3C,
; is the smaller, so the first's less the second's has the sign of the
; second's direction less the first's. Uses A, BC, DE, HL, IX
bump:   ld h, high copy         ;  8
        ld a, d                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, low copy         ;  8
        ld l, a                 ;  5  HL: the first's Y and X
        ld c, (hl)              ;  8
        inc l                   ;  5
        ld b, (hl)              ;  8  B, C: its X and Y
        ld a, e                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, low copy         ;  8
        ld l, a                 ;  5  the second's
        ld a, (hl)              ;  8
        sub c                   ;  5
        ld c, a                 ;  5  C: the second's Y less the first's
        inc l                   ;  5
        ld a, (hl)              ;  8
        sub b                   ;  5
        ld b, a                 ;  5  B: and the Xs
        ld h, high xops         ;  8
        ld a, d                 ;  5
        add a, a                ;  5
        ld l, a                 ;  5
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        push hl                 ; 12
        pop ix                  ; 16  IX: the first's X direction, its Y 12 on
        ld h, high xops         ;  8
        ld a, e                 ;  5
        add a, a                ;  5
        ld l, a                 ;  5
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: the second's
        ld a, (ix + 0)          ; 21
        sub (hl)                ;  8  the sign of the DXs' difference
        call .part              ; 18
        ld b, c                 ;  5  B: the Ys' distance
        ld c, a                 ;  5  C: what the Xs give
        ld de, 12               ; 11
        add hl, de              ; 12  HL: the second's Y direction
        ld a, (ix + 12)         ; 21
        sub (hl)                ;  8
        call .part              ; 18
        add a, c                ;  5  how fast they part
        ret p                   ; 12, or 6  0 or more: they part already
        ld a, (hl)              ;  8
        xor 1                   ;  8
        ld (hl), a              ;  8  the second's Y direction turned
        or a                    ;  5
        sbc hl, de              ; 17
        ld a, (hl)              ;  8
        xor 1                   ;  8
        ld (hl), a              ;  8  and its X
        ld a, (ix + 0)          ; 21
        xor 1                   ;  8
        ld (ix + 0), a          ; 21  the first's X
        ld a, (ix + 12)         ; 21
        xor 1                   ;  8
        ld (ix + 12), a         ; 21  and Y
        ld a, $10               ;  8  ten points
        call addsc              ; 18
        call best               ; 18
        call random             ; 18
        and 3                   ;  8  one of the four effects
        di                      ;  5  sfx and the interrupt share chan_x
        call sfx                ; 18
        ei                      ;  5
        ret                     ; 11
; .part: A = the sign of the directions' difference, B = a distance -> A
; the distance, less it, or 0
.part:  or a                    ;  5
        ret z                   ; 12, or 6
        ld a, b                 ;  5
        ret p                   ; 12, or 6
        neg                     ; 10
        ret                     ; 11

; nextwin: the next window, all its rows at once, when show has asked for it
; (pairs.asm's step, chapter 29). Uses A, BC, DE, HL
nextwin: ld a, (need)           ; 14
        or a                    ;  5
        ret z                   ; 12, or 6
        ld b, a                 ;  5  all of them
        xor a                   ;  5
        ld (need), a            ; 14
        jp rows                 ; 11

; rows: B rows of the next window, from wsrc in pmap to wdst in the table not
; shown, at 29 T-states a name: OUTI and JP NZ, the least the VDP takes while
; the paper is drawn (chapter 20); both moved on for the rows after. Uses A,
; BC, DE, HL
rows:   ld e, b                 ;  5  E: the rows
        ld hl, (wdst)           ; 17
        di                      ;  5
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12  the first name, for writing
        ei                      ;  5
        ld bc, 32               ; 11
        ld d, e                 ;  5
.past:  add hl, bc              ; 12
        dec d                   ;  5
        jr nz, .past            ; 13, or 8
        ld (wdst), hl           ; 17  where the rows after will go
        ld hl, (wsrc)           ; 17
        ld a, e                 ;  5  A: the rows
        ld de, PW - 32          ; 11
        ld c, VDP_DATA          ;  8
.row:   ld b, 32                ;  8
.name:  outi                    ; 18
        jp nz, .name            ; 11: 29 T-states a name
        add hl, de              ; 12  the next row of pmap
        dec a                   ;  5
        jr nz, .row             ; 13, or 8
        ld (wsrc), hl           ; 17
        ret                     ; 11

; touched: B, C = X, Y of one ball and D, E of the other, whose boxes meet ->
; NZ if a pixel of one is a pixel of the other. The ball's rows are in
; shifted, four bytes each, moved 0 to 7 pixels right: copy s at 64 x s.
; Uses A, BC, DE, HL
touched: ld a, d                ;  5
        sub b                   ;  5  dx: the second ball's X less the first's
        jr nc, .order           ; 13, or 8
        push bc                 ; 12  the second ball is on the left:
        push de                 ; 12  the two change places
        pop bc                  ; 11
        pop de                  ; 11
        neg                     ; 10
.order: ld l, a                 ;  5  L: dx, 0 to 15. (B, C) is the left ball
        ld a, e                 ;  5
        sub c                   ;  5  dy: the right ball's Y less the left's
        ld e, 0                 ;  8  the right ball lower: its row 0 ...
        jr nc, .lower           ; 13, or 8
        neg                     ; 10  higher: its row -dy ...
        ld e, a                 ;  5
        xor a                   ;  5  ... meets the left ball's row 0
.lower: ld c, a                 ;  5  C: the left ball's first row
        add a, e                ;  5
        sub 16                  ;  8
        neg                     ; 10
        ld b, a                 ;  5  B: the rows both cover, 16 - |dy|
        ld a, l                 ;  5
        and 3                   ;  8
        rrca                    ;  5
        rrca                    ;  5  (dx AND 3) x 64
        sla e                   ; 10
        sla e                   ; 10  + 4 x the right ball's first row
        add a, e                ;  5
        ld e, a                 ;  5
        ld d, high shifted      ;  8  DE: that row of copy dx AND 7
        bit 2, l                ; 10
        jr z, .page             ; 13, or 8
        inc d                   ;  5  copies 4 to 7 are in the next page
.page:  bit 3, l                ; 10
        jr z, .near             ; 13, or 8
        dec de                  ;  7  dx of 8 or more: a byte to the left
.near:  ld a, c                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        ld l, a                 ;  5
        ld h, high shifted      ;  8  HL: the left ball's first row, copy 0
.row:   ld a, (de)              ;  8
        and (hl)                ;  8  the first byte of the two
        ret nz                  ; 12, or 6  a pixel of both: they touch
        inc de                  ;  7
        inc l                   ;  5
        ld a, (de)              ;  8
        and (hl)                ;  8  the second
        ret nz                  ; 12, or 6
        inc de                  ;  7
        inc de                  ;  7
        inc de                  ;  7
        inc l                   ;  5
        inc l                   ;  5
        inc l                   ;  5  the next row of each
        djnz .row               ; 14, or 9
        xor a                   ;  5
        ret                     ; 11  Z: no pixel in common

; addsc: A = points, two BCD digits -> added to score, the carry taken into
; the digits before with ADC and DAA (chapter 9). Uses A, HL
addsc:  ld hl, score + 2        ; 11  the last two digits
        add a, (hl)             ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5  DEC L leaves the carry alone
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        ret                     ; 11

; best: score against hi, the first digits first -> hi is score when score
; is higher. Uses A, BC, DE, HL
best:   ld hl, score            ; 11
        ld de, hi               ; 11
        ld b, 3                 ;  8  three bytes
.byte:  ld a, (de)              ;  8  a byte of hi
        cp (hl)                 ;  8  less the same byte of score
        jr c, .new              ; 13, or 8  score's is higher: a new best
        ret nz                  ; 12, or 6  hi's is higher
        inc l                   ;  5
        inc e                   ;  5  the same: the next byte decides
        djnz .byte              ; 14, or 9
        ret                     ; 11  the same number
.new:   ld c, b                 ;  5  the bytes from here on, this one too;
        ld b, 0                 ;  8  the ones before are the same
        ldir                    ; 23, and 18 the last time
        ret                     ; 11

; random: the next of the 65,535 states of a 16-bit xorshift, x XOR x << 7,
; XOR x >> 9, XOR x << 8 -> seed, A = its high byte. Uses A, HL
random: ld hl, (seed)           ; 17
        ld a, h                 ;  5
        rra                     ;  5  bit 0 of H into the carry
        ld a, l                 ;  5
        rra                     ;  5  x << 7's high byte: that bit and L >> 1
        xor h                   ;  5
        ld h, a                 ;  5  H XOR it
        ld a, l                 ;  5
        rrca                    ;  5
        and $80                 ;  8  x << 7's low byte: L's bit 0 at bit 7
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x << 7
        ld a, h                 ;  5
        srl a                   ; 10  x >> 9, which is H >> 1
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x >> 9, which changes L alone
        xor h                   ;  5
        ld h, a                 ;  5  x XOR x << 8: H XOR L
        ld (seed), hl           ; 17
        ret                     ; 11

; joy: A = $00 for port 1, $40 for port 2 -> A = that port's register 14, a 0
; for each switch closed. Register 15's other seven bits are kept. The
; interrupts must be off. Uses A, B
joy:    ld b, a                 ;  5
        ld a, 15                ;  8
        out (PSG_ADDR), a       ; 12  register 15
        in a, (PSG_READ)        ; 12  as it is
        and $BF                 ;  8  bit 6: the port
        or b                    ;  5
        out (PSG_WRITE), a      ; 12
        ld a, 14                ;  8
        out (PSG_ADDR), a       ; 12  register 14
        in a, (PSG_READ)        ; 12  the port's pins
        ret                     ; 11

; isr: every frame. When pace gives the player a tick, last tick's
; registers are sent first, so that every tick's writes land at the same
; T-states after the interrupt, and the next tick is worked out after.
; Keeps every register it uses
isr:    push af                 ; 12
        push bc                 ; 12
        push de                 ; 12
        push hl                 ; 12
        push ix                 ; 17
        in a, (VDP_CTRL)        ; 12  the status: the signal down
        ld hl, frames           ; 11
        inc (hl)                ; 12
        call pace               ; 18  carry: the player's tick
        jr nc, .done            ; 13, or 8
        call tochip             ; 18
        call play               ; 18
.done:  pop ix                  ; 16
        pop hl                  ; 11
        pop de                  ; 11
        pop bc                  ; 11
        pop af                  ; 11
isrend: ei                      ;  5
        ret                     ; 11

; pace: carry if the player ticks in this frame. Its ticks are 313 lines
; apart, a frame of the 50 Hz machine: each frame adds its own lines to
; owed, and a tick pays 313 of them back. Uses DE, HL
pace:   ld hl, (owed)           ; 17
        ld de, (lines)          ; 22  313 or 262, from INIT
        add hl, de              ; 12
        ld de, -313             ; 11
        add hl, de              ; 12  carry: 313 lines are owed
        jr c, .paid             ; 13, or 8
        sbc hl, de              ; 17  not yet: the 313 given back, no carry
.paid:  ld (owed), hl           ; 17
        ret                     ; 11

; tochip: R0 to R10 from shadow, in order. Uses A, BC, HL
tochip: ld hl, shadow           ; 11
        ld bc, 11 << 8 | PSG_WRITE ; 11  B: the registers; C: the port
        xor a                   ;  5  R0 first
.reg:   out (PSG_ADDR), a       ; 12  the register
        inc a                   ;  5
        outi                    ; 18  its byte; HL on, and B down
        jr nz, .reg             ; 13, or 8
        ret                     ; 11

; play: the next tick into shadow: every SPEED ticks a row of each channel,
; then each channel's level, period and mixer bits, and an effect, if one
; is sounding, over channel C. Uses A, BC, DE, HL, IX
play:   ld hl, (ticks)          ; 17  one tick more
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        ld hl, tick             ; 11
        dec (hl)                ; 12
        jr nz, .sounds          ; 13, or 8
        ld (hl), SPEED          ; 11  a row
        ld hl, rowno            ; 11
        inc (hl)                ; 12  next sets it to 0 at a new bar
        ld ix, chan_a           ; 16
        call row                ; 18
        ld ix, chan_b           ; 16
        call row                ; 18
        ld ix, chan_c           ; 16
        call row                ; 18
.sounds: ld a, $BF              ;  8  all shut; bit 7 at 1, bit 6 at 0
        ld (shadow + 7), a      ; 14
        ld ix, chan_a           ; 16
        call sound              ; 18
        ld ix, chan_b           ; 16
        call sound              ; 18
        ld ix, chan_c           ; 16
        call sound              ; 18
        ld ix, chan_x           ; 16  an effect?
        ld a, (ix + WAITS)      ; 21  its ticks still to sound
        or a                    ;  5
        ret z                   ; 12, or 6  none: channel C is the music's
        dec (ix + WAITS)        ; 25
        ld a, (shadow + 7)      ; 14  the music's tone and noise on C shut
        or %00100100            ;  8
        ld (shadow + 7), a      ; 14
        jp sound                ; 11  the effect's, whose RET is play's

; row: IX = a channel -> a row: one less to wait, and at none, its pattern's
; next event, and its instrument's tables from their first byte. Uses A,
; BC, DE, HL
row:    dec (ix + WAITS)        ; 25
        ret nz                  ; 12, or 6
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
        cp END                  ;  8  the pattern's end?
        jr nz, .event           ; 13, or 8
        call next               ; 18  the song's next step
        ld a, (hl)              ;  8
        inc hl                  ;  7
.event: bit 7, a                ; 10  an instrument first?
        jr z, .note             ; 13, or 8
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
.note:  ld (ix + NOTE), a       ; 21  0 for a rest
        ld a, (hl)              ;  8  the rows it lasts
        inc hl                  ;  7
        ld (ix + WAITS), a      ; 21
        ld (ix + PATTERN), l    ; 21
        ld (ix + PATTERN + 1), h ; 21

; voice: IX = a channel -> its instrument's two tables from their first
; byte, its mixer bits and its noise's period, from instruments, 6 bytes
; each. Leaves the carry clear. Uses A, DE, HL
voice:  ld a, (ix + INSTR)      ; 21
        ld l, a                 ;  5
        add a, a                ;  5
        add a, l                ;  5  three times
        add a, a                ;  5  six times
        ld l, a                 ;  5
        ld h, 0                 ;  8
        ld de, instruments      ; 11
        add hl, de              ; 12  no carry: the table is in the ROM
        ld a, (hl)              ;  8  the volume table
        ld (ix + VOLUME), a     ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + VOLUME + 1), a ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the pitch table
        ld (ix + PITCHES), a    ; 21
        ld (ix + FIRST), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + PITCHES + 1), a ; 21
        ld (ix + FIRST + 1), a  ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the mixer's bits
        ld (ix + MIXER), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the noise's period
        ld (ix + NOISEP), a     ; 21
        ret                     ; 11

; next: the song's next step, or its first after the last: each channel's
; new pattern, and IX's in HL; the bar counted, and its row 0. Uses A, BC,
; DE, HL
next:   ld hl, (step)           ; 17
        ld de, 6                ; 11
        add hl, de              ; 12
        ld a, (hl)              ;  8
        inc hl                  ;  7
        or (hl)                 ;  8  a word 0: the end
        dec hl                  ;  7
        ld a, (barno)           ; 14
        jr nz, .keep            ; 13, or 8
        ld hl, song             ; 11  the first step again
        xor a                   ;  5
.keep:  inc a                   ;  5
        ld (barno), a           ; 14
        ld (step), hl           ; 17
        xor a                   ;  5
        ld (rowno), a           ; 14
        ld de, chan_a + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_b + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_c + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ret                     ; 11

; sound: IX = a channel -> its level, and for a note its period, in
; shadow, its tables a tick on; its tone and noise opened in R7, and R6
; its noise's period. Uses A, BC, DE, HL
sound:  ld c, 0                 ;  8  a rest's level
        ld a, (ix + NOTE)       ; 21
        or a                    ;  5
        jr z, .level            ; 13, or 8
        ld l, (ix + VOLUME)     ; 21
        ld h, (ix + VOLUME + 1) ; 21
        ld a, (hl)              ;  8  this tick's level
        cp END                  ;  8  the table's end?
        jr nz, .vstep           ; 13, or 8
        dec hl                  ;  7  the last level again
        ld c, (hl)              ;  8
        jr .pitch               ; 13
.vstep: ld c, a                 ;  5
        inc hl                  ;  7
        ld (ix + VOLUME), l     ; 21
        ld (ix + VOLUME + 1), h ; 21
.pitch: ld l, (ix + PITCHES)    ; 21
        ld h, (ix + PITCHES + 1) ; 21
        ld a, (hl)              ;  8  this tick's semitones
        cp LOOP                 ;  8
        jr nz, .hold            ; 13, or 8
        ld l, (ix + FIRST)      ; 21  the first again
        ld h, (ix + FIRST + 1)  ; 21
        ld a, (hl)              ;  8
        jr .pstep               ; 13
.hold:  cp HOLD                 ;  8
        jr nz, .pstep           ; 13, or 8
        dec hl                  ;  7  the last again
        ld a, (hl)              ;  8
        jr .pnote               ; 13
.pstep: inc hl                  ;  7
        ld (ix + PITCHES), l    ; 21
        ld (ix + PITCHES + 1), h ; 21
.pnote: add a, (ix + NOTE)      ; 21  the note they move it to
        add a, a                ;  5
        ld l, a                 ;  5
        ld h, high notes        ;  8  its period, in a page of its own
        ld e, (hl)              ;  8
        inc l                   ;  5
        ld d, (hl)              ;  8
        ld l, (ix + SHPER)      ; 21
        ld h, (ix + SHPER + 1)  ; 21
        ld (hl), e              ;  8
        inc hl                  ;  7
        ld (hl), d              ;  8
.level: ld l, (ix + SHLEV)      ; 21
        ld h, (ix + SHLEV + 1)  ; 21
        ld (hl), c              ;  8
        ld b, (ix + MIXER)      ; 21
        ld a, (shadow + 7)      ; 14
        bit 0, b                ; 10  a tone?
        jr z, .noise            ; 13, or 8
        and (ix + TMASK)        ; 21
.noise: bit 1, b                ; 10  a noise?
        jr z, .mixer            ; 13, or 8
        and (ix + NMASK)        ; 21
        ld (shadow + 7), a      ; 14
        ld a, (ix + NOISEP)     ; 21
        ld (shadow + 6), a      ; 14
        ret                     ; 11
.mixer: ld (shadow + 7), a      ; 14
        ret                     ; 11

; sfx: A = an effect -> it starts on channel C, unless the effect still
; sounding has a higher priority: then carry, and nothing changes. The
; interrupts must be off. Uses A, DE, HL, IX
sfx:    add a, a                ;  5
        add a, a                ;  5  4 bytes an effect
        ld e, a                 ;  5
        ld d, 0                 ;  8
        ld hl, effects          ; 11
        add hl, de              ; 12  its priority, instrument, note, ticks
        ld ix, chan_x           ; 16
        ld a, (ix + WAITS)      ; 21  an effect sounding?
        or a                    ;  5
        ld a, (hl)              ;  8  the new one's priority
        jr z, .take             ; 13, or 8  none
        cp (ix + PRIO)          ; 21
        ret c                   ; 12, or 6  lower: refused
.take:  ld (ix + PRIO), a       ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the instrument, $80 and its number
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + NOTE), a       ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + WAITS), a      ; 21  the ticks it sounds
        jp voice                ; 11  its tables, and no carry
